import { useCallback, useEffect, useState } from 'react'
import type { BookmarkSummary, SortOrder } from '@shared/types'
import { AddBookmark } from './AddBookmark'
import { BookmarkList } from '../components/BookmarkList'
import { EmptyState } from '../components/EmptyState'

// The main screen (US2): the add form on top, then the saved bookmarks. Polls
// briefly after a save so auto-filled details (which arrive in the background)
// appear without a manual refresh.
export function Collection(): JSX.Element {
  const [bookmarks, setBookmarks] = useState<BookmarkSummary[]>([])
  const [sort, setSort] = useState<SortOrder>('newest')
  const [loading, setLoading] = useState(true)

  const refresh = useCallback(async () => {
    const list = await window.api.listBookmarks(sort)
    setBookmarks(list)
    setLoading(false)
  }, [sort])

  useEffect(() => {
    void refresh()
  }, [refresh])

  // After a save, background metadata lands shortly; refresh a few times.
  const refreshSoon = useCallback(() => {
    void refresh()
    let n = 0
    const id = setInterval(() => {
      void refresh()
      if (++n >= 4) clearInterval(id)
    }, 700)
  }, [refresh])

  const onOpen = useCallback((id: string) => {
    void window.api.openOriginal(id)
  }, [])

  return (
    <div className="app">
      <div className="topbar">
        <h1>Bookmarks</h1>
        <label className="sort">
          Sort:{' '}
          <select value={sort} onChange={(e) => setSort(e.target.value as SortOrder)}>
            <option value="newest">Newest first</option>
            <option value="oldest">Oldest first</option>
            <option value="title">By title</option>
          </select>
        </label>
      </div>
      <div className="content">
        <AddBookmark onSaved={refreshSoon} onDuplicate={refreshSoon} />
        {loading ? null : bookmarks.length === 0 ? (
          <EmptyState
            title="No bookmarks yet"
            hint="Paste a web address above to save your first one."
          />
        ) : (
          <BookmarkList bookmarks={bookmarks} onOpen={onOpen} />
        )}
      </div>
    </div>
  )
}

