import { resolve } from 'node:path'
import { defineConfig, externalizeDepsPlugin } from 'electron-vite'
import react from '@vitejs/plugin-react'

// Bundles the three parts of the desktop app:
//  - main:    the background process (file + network + database access)
//  - preload: the safe bridge exposing named operations to the UI
//  - renderer: the React user interface
export default defineConfig({
  main: {
    plugins: [externalizeDepsPlugin()],
    build: {
      rollupOptions: {
        input: { index: resolve(__dirname, 'src/main/index.ts') }
      }
    }
  },
  preload: {
    plugins: [externalizeDepsPlugin()],
    build: {
      rollupOptions: {
        input: { index: resolve(__dirname, 'src/main/preload.ts') }
      }
    }
  },
  renderer: {
    root: resolve(__dirname, 'src/renderer'),
    resolve: {
      alias: { '@shared': resolve(__dirname, 'src/shared') }
    },
    build: {
      rollupOptions: {
        input: { index: resolve(__dirname, 'src/renderer/index.html') }
      }
    },
    plugins: [react()]
  }
})

import Database from 'better-sqlite3'
import { existsSync, mkdirSync } from 'node:fs'
import { dirname } from 'node:path'
import { applySchema } from './schema.js'
import { runMigrations } from './migrations/index.js'

export type DB = Database.Database

// Opens (creating if needed) the local SQLite database file at `dbPath`,
// applies the schema, and runs any pending migrations. Everything stays on the
// user's device — there is no server or network involved here.
export function openDatabase(dbPath: string): DB {
  if (dbPath !== ':memory:') {
    const dir = dirname(dbPath)
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true })
  }
  const db = new Database(dbPath)
  db.pragma('journal_mode = WAL')
  db.pragma('foreign_keys = ON')
  applySchema(db)
  runMigrations(db)
  return db
}

import type { DB } from './connection.js'

// Creates all tables and the full-text search index if they do not yet exist.
// Mirrors specs/001-manage-bookmarks/data-model.md. The full schema is created
// now (Foundational phase) even though the MVP only exercises bookmarks — later
// stories fill in notes, tags, saved copies, saved searches, and search.
export function applySchema(db: DB): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS bookmarks (
      id            TEXT PRIMARY KEY,
      url           TEXT NOT NULL UNIQUE,
      title         TEXT NOT NULL DEFAULT '',
      description   TEXT NOT NULL DEFAULT '',
      favicon_path  TEXT,
      note_html     TEXT,
      note_text     TEXT,
      is_read       INTEGER NOT NULL DEFAULT 0,
      is_archived   INTEGER NOT NULL DEFAULT 0,
      saved_copy_id TEXT,
      created_at    TEXT NOT NULL,
      updated_at    TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS saved_copies (
      id          TEXT PRIMARY KEY,
      bookmark_id TEXT NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE,
      kind        TEXT NOT NULL,
      file_path   TEXT,
      status      TEXT NOT NULL DEFAULT 'pending',
      captured_at TEXT
    );

    CREATE TABLE IF NOT EXISTS tags (
      id   TEXT PRIMARY KEY,
      name TEXT NOT NULL UNIQUE COLLATE NOCASE
    );

    CREATE TABLE IF NOT EXISTS bookmark_tags (
      bookmark_id TEXT NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE,
      tag_id      TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
      PRIMARY KEY (bookmark_id, tag_id)
    );

    CREATE TABLE IF NOT EXISTS saved_searches (
      id               TEXT PRIMARY KEY,
      name             TEXT NOT NULL,
      keywords         TEXT,
      tag_filter       TEXT,
      unread_only      INTEGER NOT NULL DEFAULT 0,
      include_archived INTEGER NOT NULL DEFAULT 0,
      created_at       TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS settings (
      key   TEXT PRIMARY KEY,
      value TEXT
    );

    -- Full-text index over the fields search must look inside (FR-018).
    CREATE VIRTUAL TABLE IF NOT EXISTS bookmarks_fts USING fts5(
      title, description, note_text, tags, url,
      content=''
    );

    CREATE INDEX IF NOT EXISTS idx_bookmarks_archived ON bookmarks(is_archived);
    CREATE INDEX IF NOT EXISTS idx_bookmarks_created  ON bookmarks(created_at);
  `)
}

import type { DB } from '../connection.js'

// Minimal forward-only migration runner. The schema is created idempotently in
// schema.ts; this tracks a version number so future schema changes can be
// applied in order without data loss.
interface Migration {
  version: number
  up: (db: DB) => void
}

// No migrations beyond the initial schema yet. New schema changes are appended
// here as { version, up } entries.
const migrations: Migration[] = []

export function runMigrations(db: DB): void {
  const current = (db.pragma('user_version', { simple: true }) as number) ?? 0
  const pending = migrations.filter((m) => m.version > current).sort((a, b) => a.version - b.version)
  for (const m of pending) {
    const tx = db.transaction(() => {
      m.up(db)
      db.pragma(`user_version = ${m.version}`)
    })
    tx()
  }
}

import { randomUUID } from 'node:crypto'
import type { DB } from '../db/connection.js'
import type { Bookmark, BookmarkSummary, SaveResult, SortOrder } from '@shared/types'
import { isValidWebUrl, normalizeUrl } from './urls.js'
import { fallbackTitle } from './metadata.js'

interface Deps {
  db: DB
  now?: () => string
  newId?: () => string
  // Called after a new bookmark is created so metadata/copy capture can run in
  // the background (wired to the WorkQueue in production; a no-op in tests).
  onCreated?: (bookmark: Bookmark) => void
}

type Row = {
  id: string
  url: string
  title: string
  description: string
  favicon_path: string | null
  note_html: string | null
  note_text: string | null
  is_read: number
  is_archived: number
  saved_copy_id: string | null
  created_at: string
  updated_at: string
}

function toBookmark(r: Row): Bookmark {
  return {
    id: r.id,
    url: r.url,
    title: r.title,
    description: r.description,
    faviconPath: r.favicon_path,
    noteHtml: r.note_html,
    noteText: r.note_text,
    isRead: !!r.is_read,
    isArchived: !!r.is_archived,
    savedCopyId: r.saved_copy_id,
    createdAt: r.created_at,
    updatedAt: r.updated_at
  }
}

export class BookmarksService {
  private readonly db: DB
  private readonly now: () => string
  private readonly newId: () => string
  private readonly onCreated: (b: Bookmark) => void

  constructor(deps: Deps) {
    this.db = deps.db
    this.now = deps.now ?? (() => new Date().toISOString())
    this.newId = deps.newId ?? (() => randomUUID())
    this.onCreated = deps.onCreated ?? (() => {})
  }

  private findByUrl(normalized: string): Bookmark | null {
    const row = this.db.prepare('SELECT * FROM bookmarks WHERE url = ?').get(normalized) as
      | Row
      | undefined
    return row ? toBookmark(row) : null
  }

  getById(id: string): Bookmark | null {
    const row = this.db.prepare('SELECT * FROM bookmarks WHERE id = ?').get(id) as Row | undefined
    return row ? toBookmark(row) : null
  }

  // Save a new bookmark. Rejects invalid addresses (FR-002); if the address
  // already exists, returns the existing bookmark with duplicate=true instead
  // of creating a second copy (FR-017, SC-011). Metadata capture is handed to
  // the background queue via onCreated (FR-006).
  save(input: { url: string; title?: string; description?: string }): SaveResult {
    if (!isValidWebUrl(input.url)) {
      return {
        ok: false,
        error: 'invalid-url',
        message: 'Enter a full web address starting with http:// or https://'
      }
    }
    const url = normalizeUrl(input.url)

    const existing = this.findByUrl(url)
    if (existing) {
      return { ok: true, duplicate: true, bookmark: existing }
    }

    const ts = this.now()
    const bookmark: Bookmark = {
      id: this.newId(),
      url,
      title: input.title?.trim() || fallbackTitle(url),
      description: input.description?.trim() || '',
      faviconPath: null,
      noteHtml: null,
      noteText: null,
      isRead: false,
      isArchived: false,
      savedCopyId: null,
      createdAt: ts,
      updatedAt: ts
    }

    this.db
      .prepare(
        `INSERT INTO bookmarks
           (id, url, title, description, favicon_path, note_html, note_text,
            is_read, is_archived, saved_copy_id, created_at, updated_at)
         VALUES
           (@id, @url, @title, @description, NULL, NULL, NULL, 0, 0, NULL, @createdAt, @updatedAt)`
      )
      .run({
        id: bookmark.id,
        url: bookmark.url,
        title: bookmark.title,
        description: bookmark.description,
        createdAt: bookmark.createdAt,
        updatedAt: bookmark.updatedAt
      })

    // Whether the user typed a title or not, still fetch metadata to fill in
    // what they left blank (description, favicon) — but off the UI thread.
    this.onCreated(bookmark)
    return { ok: true, duplicate: false, bookmark }
  }

  // Apply edits from a background metadata fetch without clobbering anything the
  // user typed themselves (only fills empty fields / missing favicon).
  applyFetchedMetadata(
    id: string,
    data: { title?: string | null; description?: string | null; faviconPath?: string | null }
  ): void {
    const current = this.getById(id)
    if (!current) return
    const title =
      current.title && !this.isFallback(current) ? current.title : data.title?.trim() || current.title
    const description = current.description || data.description?.trim() || ''
    const faviconPath = current.faviconPath ?? data.faviconPath ?? null
    this.db
      .prepare(
        `UPDATE bookmarks SET title=@title, description=@description,
           favicon_path=@faviconPath, updated_at=@updatedAt WHERE id=@id`
      )
      .run({ id, title, description, faviconPath, updatedAt: this.now() })
  }

  private isFallback(b: Bookmark): boolean {
    return b.title === fallbackTitle(b.url)
  }

  // User-initiated edit of title/description (FR-004).
  update(id: string, patch: { title?: string; description?: string }): Bookmark | null {
    const current = this.getById(id)
    if (!current) return null
    const title = patch.title !== undefined ? patch.title.trim() || fallbackTitle(current.url) : current.title
    const description = patch.description !== undefined ? patch.description.trim() : current.description
    this.db
      .prepare('UPDATE bookmarks SET title=@title, description=@description, updated_at=@updatedAt WHERE id=@id')
      .run({ id, title, description, updatedAt: this.now() })
    return this.getById(id)
  }

  // List active (non-archived) bookmarks in the chosen order (FR-008, FR-032).
  listActive(sort: SortOrder = 'newest'): BookmarkSummary[] {
    const orderBy =
      sort === 'title'
        ? 'title COLLATE NOCASE ASC'
        : sort === 'oldest'
          ? 'created_at ASC'
          : 'created_at DESC'
    const rows = this.db
      .prepare(`SELECT * FROM bookmarks WHERE is_archived = 0 ORDER BY ${orderBy}`)
      .all() as Row[]
    return rows.map((r) => this.withDerived(toBookmark(r)))
  }

  private withDerived(b: Bookmark): BookmarkSummary {
    const tags = this.db
      .prepare(
        `SELECT t.name FROM tags t
           JOIN bookmark_tags bt ON bt.tag_id = t.id
          WHERE bt.bookmark_id = ? ORDER BY t.name COLLATE NOCASE`
      )
      .all(b.id)
      .map((r) => (r as { name: string }).name)
    const copy = this.db
      .prepare('SELECT status FROM saved_copies WHERE bookmark_id = ?')
      .get(b.id) as { status: BookmarkSummary['savedCopyStatus'] } | undefined
    return { ...b, tags, savedCopyStatus: copy?.status ?? null }
  }
}

import type { Bookmark } from '@shared/types'
import type { BookmarksService } from './bookmarks.js'
import type { FileStore } from '../storage/files.js'
import { fetchMetadata, type FetchFn } from './metadata.js'

// Background job: fetch a new bookmark's page metadata and favicon, then fill in
// the fields the user left blank. Runs on the WorkQueue so it never blocks the
// UI (FR-003, FR-006). Failures are swallowed by the queue and simply leave the
// fallback label in place (FR-005).
export function makeMetadataJob(
  bookmark: Bookmark,
  deps: { bookmarks: BookmarksService; files: FileStore; fetchFn?: FetchFn }
): () => Promise<void> {
  const fetchFn = deps.fetchFn ?? (globalThis.fetch as unknown as FetchFn)
  return async () => {
    const meta = await fetchMetadata(bookmark.url, fetchFn)

    let faviconPath: string | null = null
    if (meta.faviconUrl) {
      try {
        const res = await (globalThis.fetch as typeof fetch)(meta.faviconUrl)
        if (res.ok) {
          const buf = Buffer.from(await res.arrayBuffer())
          const ext = meta.faviconUrl.split('.').pop()?.split('?')[0]?.slice(0, 5) || 'ico'
          faviconPath = deps.files.writeFavicon(bookmark.id, ext, buf)
        }
      } catch {
        // favicon is optional; ignore fetch failures
      }
    }

    deps.bookmarks.applyFetchedMetadata(bookmark.id, {
      title: meta.title,
      description: meta.description,
      faviconPath
    })
  }
}

import { ipcMain, shell } from 'electron'
import type { DB } from './db/connection.js'
import type { SortOrder } from '@shared/types'
import { BookmarksService } from './services/bookmarks.js'
import { FileStore } from './storage/files.js'
import { WorkQueue } from './services/queue.js'
import { makeMetadataJob } from './services/captureMetadata.js'

// Named operations the UI can call (contracts/bookmark-operations.md). Each
// channel maps to one method; the renderer reaches them through the preload
// bridge. All file/network/database access stays here in the main process.
export const CHANNELS = {
  saveBookmark: 'bookmark:save',
  updateBookmark: 'bookmark:update',
  listBookmarks: 'bookmark:list',
  getBookmark: 'bookmark:get',
  openOriginal: 'bookmark:open'
} as const

export function registerIpc(db: DB, dataDir: string): void {
  const files = new FileStore(`${dataDir}/saved-copies`)
  const queue = new WorkQueue()
  const bookmarks = new BookmarksService({
    db,
    onCreated: (b) => queue.enqueue(makeMetadataJob(b, { bookmarks, files }))
  })

  ipcMain.handle(CHANNELS.saveBookmark, (_e, input: { url: string; title?: string; description?: string }) =>
    bookmarks.save(input)
  )

  ipcMain.handle(CHANNELS.updateBookmark, (_e, id: string, patch: { title?: string; description?: string }) =>
    bookmarks.update(id, patch)
  )

  ipcMain.handle(CHANNELS.listBookmarks, (_e, sort: SortOrder) => bookmarks.listActive(sort))

  ipcMain.handle(CHANNELS.getBookmark, (_e, id: string) => bookmarks.getById(id))

  ipcMain.handle(CHANNELS.openOriginal, async (_e, id: string) => {
    const b = bookmarks.getById(id)
    if (b) await shell.openExternal(b.url)
    return { ok: true }
  })
}

