    const current = this.getById(id)
    if (!current) return
    const title =
      current.title && !this.isFallback(current) ? current.title : data.title?.trim() || current.title
    const description = current.description || data.description?.trim() || ''
    const faviconPath = current.faviconPath ?? data.faviconPath ?? null
    this.db
      .prepare(
        `UPDATE bookmarks SET title=@title, description=@description,
           favicon_path=@faviconPath, updated_at=@updatedAt WHERE id=@id`
      )
      .run({ id, title, description, faviconPath, updatedAt: this.now() })
  }

  private isFallback(b: Bookmark): boolean {
    return b.title === fallbackTitle(b.url)
  }

  // User-initiated edit of title/description (FR-004).
  update(id: string, patch: { title?: string; description?: string }): Bookmark | null {
    const current = this.getById(id)
    if (!current) return null
    const title = patch.title !== undefined ? patch.title.trim() || fallbackTitle(current.url) : current.title
    const description = patch.description !== undefined ? patch.description.trim() : current.description
    this.db
      .prepare('UPDATE bookmarks SET title=@title, description=@description, updated_at=@updatedAt WHERE id=@id')
      .run({ id, title, description, updatedAt: this.now() })
    return this.getById(id)
  }

  // List active (non-archived) bookmarks in the chosen order (FR-008, FR-032).
  listActive(sort: SortOrder = 'newest'): BookmarkSummary[] {
    const orderBy =
      sort === 'title'
        ? 'title COLLATE NOCASE ASC'
        : sort === 'oldest'
          ? 'created_at ASC'
          : 'created_at DESC'
    const rows = this.db
      .prepare(`SELECT * FROM bookmarks WHERE is_archived = 0 ORDER BY ${orderBy}`)
      .all() as Row[]
    return rows.map((r) => this.withDerived(toBookmark(r)))
  }

  private withDerived(b: Bookmark): BookmarkSummary {
    const tags = this.db
      .prepare(
        `SELECT t.name FROM tags t
           JOIN bookmark_tags bt ON bt.tag_id = t.id
          WHERE bt.bookmark_id = ? ORDER BY t.name COLLATE NOCASE`
      )
      .all(b.id)
      .map((r) => (r as { name: string }).name)
    const copy = this.db
      .prepare('SELECT status FROM saved_copies WHERE bookmark_id = ?')
      .get(b.id) as { status: BookmarkSummary['savedCopyStatus'] } | undefined
    return { ...b, tags, savedCopyStatus: copy?.status ?? null }
