import { randomUUID } from 'node:crypto'
import type { DB } from '../db/connection'
import type { Bookmark, BookmarkSummary, BookmarkEdit, SaveResult, SortOrder, UpdateResult } from '@shared/types'
import { isValidWebUrl, normalizeUrl } from './urls'
import { fallbackTitle } from './metadata'
import { sanitizeNoteHtml, htmlToText } from './notes'

interface Deps {
  db: DB
  now?: () => string
  newId?: () => string
  // Called after a new bookmark is created so metadata/copy capture can run in
  // the background (wired to the WorkQueue in production; a no-op in tests).
  onCreated?: (bookmark: Bookmark) => void
}

type Row = {
  id: string
  url: string
  title: string
  description: string
  favicon_path: string | null
  note_html: string | null
  note_text: string | null
  is_read: number
  is_archived: number
  saved_copy_id: string | null
  created_at: string
  updated_at: string
}

function toBookmark(r: Row): Bookmark {
  return {
    id: r.id,
    url: r.url,
    title: r.title,
    description: r.description,
    faviconPath: r.favicon_path,
    noteHtml: r.note_html,
    noteText: r.note_text,
    isRead: !!r.is_read,
    isArchived: !!r.is_archived,
    savedCopyId: r.saved_copy_id,
    createdAt: r.created_at,
    updatedAt: r.updated_at
  }
}

export class BookmarksService {
  private readonly db: DB
  private readonly now: () => string
  private readonly newId: () => string
  private readonly onCreated: (b: Bookmark) => void

  constructor(deps: Deps) {
    this.db = deps.db
    this.now = deps.now ?? (() => new Date().toISOString())
    this.newId = deps.newId ?? (() => randomUUID())
    this.onCreated = deps.onCreated ?? (() => {})
  }

  private findByUrl(normalized: string): Bookmark | null {
    const row = this.db.prepare('SELECT * FROM bookmarks WHERE url = ?').get(normalized) as
      | Row
      | undefined
    return row ? toBookmark(row) : null
  }

  getById(id: string): Bookmark | null {
    const row = this.db.prepare('SELECT * FROM bookmarks WHERE id = ?').get(id) as Row | undefined
    return row ? toBookmark(row) : null
  }

  // Save a new bookmark. Rejects invalid addresses (FR-002); if the address
  // already exists, returns the existing bookmark with duplicate=true instead
  // of creating a second copy (FR-017, SC-011). Metadata capture is handed to
  // the background queue via onCreated (FR-006).
  save(input: { url: string; title?: string; description?: string }): SaveResult {
    if (!isValidWebUrl(input.url)) {
      return {
        ok: false,
        error: 'invalid-url',
        message: 'Enter a full web address starting with http:// or https://'
      }
    }
    const url = normalizeUrl(input.url)

    const existing = this.findByUrl(url)
    if (existing) {
      return { ok: true, duplicate: true, bookmark: existing }
    }

    const ts = this.now()
    const bookmark: Bookmark = {
      id: this.newId(),
      url,
      title: input.title?.trim() || fallbackTitle(url),
      description: input.description?.trim() || '',
      faviconPath: null,
      noteHtml: null,
      noteText: null,
      isRead: false,
      isArchived: false,
      savedCopyId: null,
      createdAt: ts,
      updatedAt: ts
    }

    this.db
      .prepare(
        `INSERT INTO bookmarks
           (id, url, title, description, favicon_path, note_html, note_text,
            is_read, is_archived, saved_copy_id, created_at, updated_at)
         VALUES
           (@id, @url, @title, @description, NULL, NULL, NULL, 0, 0, NULL, @createdAt, @updatedAt)`
      )
      .run({
        id: bookmark.id,
        url: bookmark.url,
        title: bookmark.title,
        description: bookmark.description,
        createdAt: bookmark.createdAt,
        updatedAt: bookmark.updatedAt
      })

    // Whether the user typed a title or not, still fetch metadata to fill in
    // what they left blank (description, favicon) — but off the UI thread.
    this.onCreated(bookmark)
    return { ok: true, duplicate: false, bookmark }
  }

  // Apply edits from a background metadata fetch without clobbering anything the
  // user typed themselves (only fills empty fields / missing favicon).
  applyFetchedMetadata(
    id: string,
    data: { title?: string | null; description?: string | null; faviconPath?: string | null }
  ): void {
    const current = this.getById(id)
    if (!current) return
    const title =
      current.title && !this.isFallback(current) ? current.title : data.title?.trim() || current.title
    const description = current.description || data.description?.trim() || ''
    const faviconPath = current.faviconPath ?? data.faviconPath ?? null
    this.db
      .prepare(
        `UPDATE bookmarks SET title=@title, description=@description,
           favicon_path=@faviconPath, updated_at=@updatedAt WHERE id=@id`
      )
      .run({ id, title, description, faviconPath, updatedAt: this.now() })
  }

  private isFallback(b: Bookmark): boolean {
    return b.title === fallbackTitle(b.url)
  }

  // User-initiated edit of title/description (FR-004).
  update(id: string, patch: { title?: string; description?: string }): Bookmark | null {
    const current = this.getById(id)
    if (!current) return null
    const title = patch.title !== undefined ? patch.title.trim() || fallbackTitle(current.url) : current.title
    const description = patch.description !== undefined ? patch.description.trim() : current.description
    this.db
      .prepare('UPDATE bookmarks SET title=@title, description=@description, updated_at=@updatedAt WHERE id=@id')
      .run({ id, title, description, updatedAt: this.now() })
    return this.getById(id)
  }

  // List active (non-archived) bookmarks in the chosen order (FR-008, FR-032).
  listActive(sort: SortOrder = 'newest'): BookmarkSummary[] {
    const orderBy =
      sort === 'title'
        ? 'title COLLATE NOCASE ASC'
        : sort === 'oldest'
          ? 'created_at ASC'
          : 'created_at DESC'
    const rows = this.db
      .prepare(`SELECT * FROM bookmarks WHERE is_archived = 0 ORDER BY ${orderBy}`)
      .all() as Row[]
    return rows.map((r) => this.withDerived(toBookmark(r)))
  }

  private withDerived(b: Bookmark): BookmarkSummary {
    const tags = this.db
      .prepare(
        `SELECT t.name FROM tags t
           JOIN bookmark_tags bt ON bt.tag_id = t.id
          WHERE bt.bookmark_id = ? ORDER BY t.name COLLATE NOCASE`
      )
      .all(b.id)
      .map((r) => (r as { name: string }).name)
    const copy = this.db
      .prepare('SELECT status FROM saved_copies WHERE bookmark_id = ?')
      .get(b.id) as { status: BookmarkSummary['savedCopyStatus'] } | undefined
    return { ...b, tags, savedCopyStatus: copy?.status ?? null }
  }
}

import { ipcMain, shell } from 'electron'
import { readFileSync } from 'node:fs'
import type { DB } from './db/connection'
import type { SortOrder, SavedCopyView } from '@shared/types'
import { CHANNELS } from '@shared/channels'
import { BookmarksService } from './services/bookmarks'
import { SavedCopiesService } from './services/savedCopies'
import { FileStore } from './storage/files'
import { WorkQueue } from './services/queue'
import { makeIngestJob } from './services/ingest'

// Registers the handlers for the named operations the UI can call
// (contracts/bookmark-operations.md, contracts/capture-operations.md). Each
// channel maps to one method; the renderer reaches them through the preload
// bridge. All file/network/database access stays here in the main process.
export function registerIpc(db: DB, dataDir: string): void {
  const files = new FileStore(`${dataDir}/saved-copies`)
  const queue = new WorkQueue()
  const savedCopies = new SavedCopiesService(db)
  const bookmarks = new BookmarksService({
    db,
    // On save, fetch metadata + capture the saved copy in the background.
    onCreated: (b) => queue.enqueue(makeIngestJob(b, { bookmarks, savedCopies, files }))
  })

  ipcMain.handle(CHANNELS.saveBookmark, (_e, input: { url: string; title?: string; description?: string }) =>
    bookmarks.save(input)
  )

  ipcMain.handle(CHANNELS.updateBookmark, (_e, id: string, patch: { title?: string; description?: string }) =>
    bookmarks.update(id, patch)
  )

  ipcMain.handle(CHANNELS.listBookmarks, (_e, sort: SortOrder) => bookmarks.listActive(sort))

  ipcMain.handle(CHANNELS.getBookmark, (_e, id: string) => bookmarks.getById(id))

  ipcMain.handle(CHANNELS.openOriginal, async (_e, id: string) => {
    const b = bookmarks.getById(id)
    if (b) await shell.openExternal(b.url)
    return { ok: true }
  })

  // Serve the locally stored saved copy for offline viewing — never re-fetch the
  // live page (FR-007). Reader copies return sanitized HTML ready to render;
  // PDFs return the local file path.
  ipcMain.handle(CHANNELS.getSavedCopy, (_e, bookmarkId: string): SavedCopyView => {
    const copy = savedCopies.getForBookmark(bookmarkId)
    if (!copy || copy.status !== 'captured' || !copy.filePath) {
      return { status: copy && copy.status === 'pending' ? 'pending' : 'unavailable' }
    }
    if (copy.kind === 'reader') {
      return { status: 'captured', kind: 'reader', html: readFileSync(copy.filePath, 'utf8') }
    }
    return { status: 'captured', kind: 'pdf', filePath: copy.filePath }
  })

  // Open a retained PDF in the operating system's default viewer (works offline
  // from the local copy).
  ipcMain.handle(CHANNELS.openSavedCopyExternal, async (_e, bookmarkId: string) => {
    const copy = savedCopies.getForBookmark(bookmarkId)
    if (copy?.filePath) await shell.openPath(copy.filePath)
    return { ok: true }
  })
}

