              onClearAll={clearAll}
              canSave={isSearching}
              onSaveSearch={saveCurrentSearch}
              savedSearches={savedSearches}
              activeSavedId={activeSavedId}
              onRunSaved={runSaved}
              onDeleteSaved={deleteSaved}
            />
