import { useCallback, useEffect, useState } from 'react'
import type { BookmarkSummary, SortOrder } from '@shared/types'
import { AddBookmark } from './AddBookmark'
import { Reader } from './Reader'
import { Archived } from './Archived'
import { BookmarkDetail } from './BookmarkDetail'
import { BookmarkList } from '../components/BookmarkList'
import { EmptyState } from '../components/EmptyState'

type View = 'active' | 'archived'

// The main screen: the add form and saved bookmarks, with an All/Archived
// switch, per-bookmark actions (open, saved copy, edit, restore), an edit/detail
// panel, and the saved-copy reader. Re-saving a duplicate opens the existing
// bookmark for editing (FR-017).
export function Collection(): JSX.Element {
  const [view, setView] = useState<View>('active')
  const [bookmarks, setBookmarks] = useState<BookmarkSummary[]>([])
  const [sort, setSort] = useState<SortOrder>('newest')
  const [loading, setLoading] = useState(true)
  const [notice, setNotice] = useState<string | null>(null)
  const [highlightId, setHighlightId] = useState<string | null>(null)
  const [readerFor, setReaderFor] = useState<BookmarkSummary | null>(null)
  const [detailFor, setDetailFor] = useState<string | null>(null)

  const refresh = useCallback(async () => {
    const list =
      view === 'active' ? await window.api.listBookmarks(sort) : await window.api.listArchived(sort)
    setBookmarks(list)
    setLoading(false)
  }, [sort, view])

  useEffect(() => {
    void refresh()
  }, [refresh])

  // After a save, background metadata/copy lands shortly; refresh a few times.
  const refreshSoon = useCallback(() => {
    setNotice(null)
    setHighlightId(null)
    void refresh()
    let n = 0
    const id = setInterval(() => {
      void refresh()
      if (++n >= 4) clearInterval(id)
    }, 700)
  }, [refresh])

  // FR-017: re-saving an existing address opens that bookmark for editing rather
  // than silently doing nothing or making a duplicate.
  const onDuplicate = useCallback((id: string) => {
    setNotice("You've already saved this — opening it so you can update it.")
    setDetailFor(id)
  }, [])

  const onOpen = useCallback((id: string) => {
    void window.api.openOriginal(id)
  }, [])

  const onOpenCopy = useCallback(
    (id: string) => setReaderFor(bookmarks.find((b) => b.id === id) ?? null),
    [bookmarks]
  )

  const onRestore = useCallback(
    async (id: string) => {
      await window.api.setArchived(id, false)
      await refresh()
    },
    [refresh]
  )

  const readerTitle = readerFor?.title ?? ''

  return (
    <div className="app">
      <div className="topbar">
        <h1>Bookmarks</h1>
        <nav className="views">
          <button
            className={view === 'active' ? '' : 'secondary'}
            onClick={() => setView('active')}
          >
            All
          </button>
          <button
            className={view === 'archived' ? '' : 'secondary'}
            onClick={() => setView('archived')}
          >
            Archived
          </button>
        </nav>
        <label className="sort">
          Sort:{' '}
          <select value={sort} onChange={(e) => setSort(e.target.value as SortOrder)}>
            <option value="newest">Newest first</option>
            <option value="oldest">Oldest first</option>
            <option value="title">By title</option>
          </select>
        </label>
      </div>
      <div className="content">
        {view === 'active' && <AddBookmark onSaved={refreshSoon} onDuplicate={onDuplicate} />}
        {notice && <div className="notice">{notice}</div>}
        {loading ? null : view === 'archived' ? (
          <Archived
            bookmarks={bookmarks}
            onOpenCopy={onOpenCopy}
            onEdit={setDetailFor}
            onRestore={onRestore}
          />
        ) : bookmarks.length === 0 ? (
          <EmptyState
            title="No bookmarks yet"
            hint="Paste a web address above to save your first one."
          />
        ) : (
          <BookmarkList
            bookmarks={bookmarks}
            onOpen={onOpen}
            onOpenCopy={onOpenCopy}
            onEdit={setDetailFor}
            highlightId={highlightId}
          />
        )}
      </div>

      {readerFor && (
        <Reader bookmarkId={readerFor.id} title={readerTitle} onClose={() => setReaderFor(null)} />
      )}
      {detailFor && (
        <BookmarkDetail
          bookmarkId={detailFor}
          onClose={() => setDetailFor(null)}
          onChanged={refresh}
        />
      )}
    </div>
  )
}

