      '<!DOCTYPE NETSCAPE-Bookmark-file-1>',
      '<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">',
      '<TITLE>Bookmarks</TITLE>',
      '<H1>Bookmarks</H1>',
      '<DL><p>',
      ...lines,
      '</DL><p>',
      ''
    ].join('\n')
  }

  countAll(): number {
    return (this.db.prepare('SELECT COUNT(*) AS n FROM bookmarks').get() as { n: number }).n
  }
