:root {
  --bg: #f7f7f8;
  --panel: #ffffff;
  --border: #e2e2e5;
  --text: #1c1c1e;
  --muted: #6b6b70;
  --accent: #2f6fed;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.app { display: flex; flex-direction: column; height: 100vh; }

.topbar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 20px;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
}
.topbar h1 { font-size: 18px; margin: 0; flex: 1; }
.topbar .sort { font-size: 13px; color: var(--muted); }

.content { flex: 1; overflow-y: auto; padding: 20px; }

.add-form { display: flex; gap: 8px; flex-wrap: wrap; }
.add-form input[type="url"] { flex: 1; min-width: 280px; }

input, select, button, textarea {
  font: inherit;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
}
button {
  background: var(--accent);
  color: #fff;
  border: none;
  cursor: pointer;
}
button.secondary { background: #ececed; color: var(--text); }
button:disabled { opacity: 0.5; cursor: default; }

.error { color: #c0392b; font-size: 13px; margin-top: 6px; }

.bookmark-list { list-style: none; margin: 16px 0 0; padding: 0; display: grid; gap: 10px; }
.bookmark {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px 14px;
}
.bookmark .favicon { width: 20px; height: 20px; border-radius: 4px; margin-top: 2px; background: #eee; }
.bookmark .body { flex: 1; min-width: 0; }
.bookmark .title { font-weight: 600; }
.bookmark .desc { color: var(--muted); font-size: 13px; margin-top: 2px;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.bookmark .url { color: var(--accent); font-size: 12px; margin-top: 4px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bookmark .status { font-size: 11px; color: var(--muted); margin-top: 4px; }
.bookmark .actions { display: flex; gap: 6px; }

.empty { text-align: center; color: var(--muted); padding: 60px 20px; }
.empty h2 { color: var(--text); }

.notice {
  margin: 12px 0 0;
  padding: 10px 14px;
  background: #eef4ff;
  border: 1px solid #cfe0ff;
  border-radius: 8px;
  color: #204080;
  font-size: 14px;
}

.bookmark.highlight {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px rgba(47, 111, 237, 0.25);
  animation: flash 1.6s ease-out;
}
@keyframes flash {
  0% { background: #eef4ff; }
  100% { background: var(--panel); }
}

/* Saved-copy reader overlay (US3) */
.reader-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.35);
  display: flex;
  justify-content: center;
  align-items: stretch;
  padding: 30px;
}
.reader-panel {
  background: #fff;
  border-radius: 12px;
  max-width: 820px;
  width: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.reader-panel .reader-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 18px;
  border-bottom: 1px solid var(--border);
}
.reader-panel .reader-head .title { flex: 1; font-weight: 600; }
.reader-body { overflow-y: auto; padding: 24px 28px; line-height: 1.6; }
.reader-body img { max-width: 100%; height: auto; }
.reader-body pre { white-space: pre-wrap; }
.reader-pdf { flex: 1; border: none; width: 100%; }
.reader-message { padding: 40px; text-align: center; color: var(--muted); }

.topbar .views { display: flex; gap: 6px; }
.topbar .views button { padding: 6px 12px; font-size: 13px; }

button.danger { background: #c0392b; color: #fff; }

/* Detail / edit form */
.detail-form label { display: block; font-size: 13px; color: var(--muted); margin-bottom: 14px; }
.detail-form label input,
.detail-form label textarea { display: block; width: 100%; margin-top: 4px; color: var(--text); }
.detail-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-top: 8px; }
.confirm-delete { display: inline-flex; gap: 8px; align-items: center; font-size: 13px; color: #c0392b; }

/* Note editor */
.note-editor { margin-top: 4px; border: 1px solid var(--border); border-radius: 8px; overflow: hidden; }
.note-toolbar { display: flex; gap: 4px; padding: 6px; background: #fafafa; border-bottom: 1px solid var(--border); }
.note-toolbar button { padding: 4px 10px; font-size: 13px; }
.note-area { min-height: 90px; padding: 10px 12px; outline: none; font-size: 14px; line-height: 1.5; }
.note-area:empty::before { content: attr(data-placeholder); color: var(--muted); }
.note-area ul, .note-area ol { margin: 6px 0; padding-left: 22px; }
.note-area a { color: var(--accent); }

/* Search + filters */
.search { margin-top: 14px; display: flex; flex-direction: column; gap: 8px; }
.search-row { display: flex; gap: 8px; }
.search-box { flex: 1; }
.active-filter { font-size: 13px; color: var(--muted); display: flex; align-items: center; gap: 8px; }
.saved-searches { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; font-size: 13px; }
.saved-label { color: var(--muted); }

/* Tag chips */
.tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: #eef1f6;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 2px 8px;
  font-size: 12px;
  color: #333;
}
.tag-chip.clickable { cursor: pointer; }
.tag-chip.clickable:hover { background: #e3e9f5; }
.tag-chip.active { outline: 2px solid var(--accent); }
.tag-chip .chip-x, .saved-run {
  border: none; background: none; padding: 0; margin: 0; cursor: pointer; color: inherit; font: inherit;
}
.tag-chip .chip-x { color: var(--muted); font-size: 14px; line-height: 1; }
.tag-chip .chip-x:hover { color: #c0392b; }
.clickable-wrap { cursor: default; }

.card-tags { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 6px; }
.card-tags .tag-chip { background: #eef4ff; border-color: #cfe0ff; }

/* Tag input (detail) */
.tag-input { display: flex; flex-direction: column; gap: 6px; margin-top: 4px; }
.tag-chips { display: flex; gap: 6px; flex-wrap: wrap; }
.tag-suggestions { display: flex; gap: 6px; flex-wrap: wrap; }
.tag-suggestions button { padding: 2px 8px; font-size: 12px; border-radius: 999px; }

/* Batch toolbar + selection */
.batch-toolbar {
  position: sticky;
  top: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin: 14px 0 4px;
  padding: 10px 12px;
  background: #fff7e6;
  border: 1px solid #f0d9a8;
  border-radius: 10px;
}
.batch-toolbar button { padding: 5px 10px; font-size: 13px; }
.batch-count { font-weight: 600; font-size: 13px; }
.batch-sep { flex: 0 0 1px; align-self: stretch; background: #f0d9a8; margin: 0 2px; }
.bookmark .select-box { margin-top: 4px; width: 16px; height: 16px; }
.bookmark.selected { border-color: var(--accent); background: #f5f9ff; }

/* Import / export bar */
.io-bar { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.io-bar button { padding: 6px 12px; font-size: 13px; }
.io-progress, .io-message { font-size: 12px; color: var(--muted); }

.unread-toggle { font-size: 13px; color: var(--muted); display: flex; align-items: center; gap: 5px; }
.unread-dot { color: var(--accent); font-size: 11px; margin-right: 8px; }

