  // PDFs return the local file path.
  ipcMain.handle(CHANNELS.getSavedCopy, (_e, bookmarkId: string): SavedCopyView => {
    const copy = savedCopies.getForBookmark(bookmarkId)
    if (!copy || copy.status !== 'captured' || !copy.filePath) {
